import{c as a,Q as i,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"OpenAI o3 and o4-mini System Card","description":"","frontmatter":{"url":"https://cdn.openai.com/pdf/2221c875-02dc-4789-800b-e7758f3722c1/o3-and-o4-mini-system-card.pdf","title":"OpenAI o3 and o4-mini System Card","archived_date":"2026-06-24T00:00:00.000Z","authors":["OpenAI"],"domains":["system-card"],"pdf_path":"pdfs/openai-o3-o4-mini-system-card.pdf","published_date":"2025-04-16T00:00:00.000Z","source_url":"https://cdn.openai.com/pdf/2221c875-02dc-4789-800b-e7758f3722c1/o3-and-o4-mini-system-card.pdf"},"headers":[],"relativePath":"research/papers/2025-04-16-openai-o3-o4-mini-system-card.md","filePath":"research/papers/2025-04-16-openai-o3-o4-mini-system-card.md","lastUpdated":1785909234000}'),n={name:"research/papers/2025-04-16-openai-o3-o4-mini-system-card.md"};function t(s,e,d,l,c,m){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="openai-o3-and-o4-mini-system-card" tabindex="-1">OpenAI o3 and o4-mini System Card <a class="header-anchor" href="#openai-o3-and-o4-mini-system-card" aria-label="Permalink to &quot;OpenAI o3 and o4-mini System Card&quot;">​</a></h1><p><strong>Source</strong>: <a href="https://cdn.openai.com/pdf/2221c875-02dc-4789-800b-e7758f3722c1/o3-and-o4-mini-system-card.pdf" target="_blank" rel="noreferrer">https://cdn.openai.com/pdf/2221c875-02dc-4789-800b-e7758f3722c1/o3-and-o4-mini-system-card.pdf</a><strong>Published</strong>: April 16, 2025 <strong>PDF</strong>: <code>research/papers/pdfs/openai-o3-o4-mini-system-card.pdf</code> (33 pp, full text archived)</p><hr><h2 id="摘要-依官方-pdf-第-1–3-頁-overview-整理" tabindex="-1">摘要（依官方 PDF 第 1–3 頁 overview 整理） <a class="header-anchor" href="#摘要-依官方-pdf-第-1–3-頁-overview-整理" aria-label="Permalink to &quot;摘要（依官方 PDF 第 1–3 頁 overview 整理）&quot;">​</a></h2><blockquote><p>OpenAI o3 and OpenAI o4-mini combine state-of-the-art reasoning with full tool capabilities — web browsing, Python, image and file analysis, image generation, canvas, automations, file search, and memory. These models excel at solving complex math, coding, and scientific challenges while demonstrating strong visual perception and analysis. The models use tools in their chains of thought to augment their capabilities... This is the first launch and system card to be released under Version 2 of our Preparedness Framework. （引自 system card §1 Introduction）</p></blockquote><ul><li>o3 與 o4-mini 結合 SOTA 推理與完整工具能力（web browsing、Python、影像/檔案分析、影像生成、canvas、automations、file search、memory）。</li><li>模型在 chain of thought 中主動調用工具（裁切/轉換影像、搜尋網頁、用 Python 分析資料）。</li><li>為<strong>首個依 Preparedness Framework Version 2 發布</strong>的 launch 與 system card。</li></ul><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="模型與定位" tabindex="-1">模型與定位 <a class="header-anchor" href="#模型與定位" aria-label="Permalink to &quot;模型與定位&quot;">​</a></h3><ul><li>o-series 推理模型 + 完整 agentic 工具鏈；強於複雜 math/coding/科學任務與視覺感知分析。</li><li>安全方法延續 deliberative alignment。</li></ul><h3 id="關鍵能力-安全評估數字" tabindex="-1">關鍵能力 / 安全評估數字 <a class="header-anchor" href="#關鍵能力-安全評估數字" aria-label="Permalink to &quot;關鍵能力 / 安全評估數字&quot;">​</a></h3><ul><li>Preparedness Framework V2，三個 Tracked Categories：<strong>Biological and Chemical Capability、Cybersecurity、AI Self-improvement</strong>。</li><li>SAG 裁定：<strong>o3 與 o4-mini 在三類別中均未達 High threshold</strong>。</li><li>報告詳列各類別評測並更新風險緩解工作（jailbreak / refusal / hallucination 等具體數字見 PDF 全文對應章節）。</li></ul><h3 id="workspace-關聯-評估" tabindex="-1">Workspace 關聯（評估） <a class="header-anchor" href="#workspace-關聯-評估" aria-label="Permalink to &quot;Workspace 關聯（評估）&quot;">​</a></h3><ul><li>「推理鏈中調用工具」對應本庫 agent 工具使用模式（Bash/WebFetch/Grep 等）；其 memory 工具能力呼應任務 A 諸篇 agent memory 主題。</li><li>Preparedness V2 三類別（含 AI Self-improvement）對應 core.md「harness 自我改進」需 APPLY 前置 gate 的紅線思維。</li><li>⚠️ 依官方公開資訊整理；jailbreak/refusal/hallucination 量化以 PDF 全文為準。</li></ul>',14)])])}const u=a(n,[["render",t]]);export{h as __pageData,u as default};
